[1314] = "右键点击以插入已装备的饰品。",
-- d0cd6f0d English: Right-click to insert your target's cast or a recent cast.
[1315] = "右键点击以插入你目标正在施放的法术或最近施放的法术。",
-- 2702ffe0 English: Search or drag an item here
[1316] = "在此搜索或拖入物品",
-- d27b40b5 English: Select an effect to edit its name, type and type-specific settings. The icon
--     previews it live. Sequence sections edit animation, color, pulse or custom frames in order.
--     Duplicate creates an independent effect. Drag a sequence card surface to reorder it; fields
